""""
Compile a consolidated report in the 'merging' sheet of an Excel workbook.

Logic
------
* The workbook contains monthly data sheets (e.g. 'SH1', 'RP1') each holding an
  'ID' column and a 'QTY' column, plus a 'merging' report sheet whose column B
  holds the IDs.
* For every ID in 'merging'!B2:B11:
      - Column C  <- matching QTY from sheet 'SH1'
      - Column D  <- matching QTY from sheet 'RP1'
* If the ID is missing in a source sheet, or the found QTY cell is blank /
  contains an error (e.g. '#N/A'), a "-" is written instead.
* The result is saved as 'output.xlsx' (a copy of the input workbook).
* Because the script reads every data sheet fresh from the file, simply re-run
  it each month (new monthly sheets can be added to the SHEET_TO_COLUMN map
  below) and the merged report is rebuilt/updated automatically.
"""

import sys
import openpyxl


# ---------------------------------------------------------------------------
# Configuration: destination column in 'merging' for each source data sheet
# ---------------------------------------------------------------------------
SHEET_TO_COLUMN = {
    "SH1": 3,   # column C
    "RP1": 4,   # column D
}
MERGE_SHEET = "merging"
ID_COLUMN_IN_MERGE = 2          # column B of the merging sheet
ANSWER_ROWS = range(2, 12)      # rows 2..11


def norm_key(value):
    """Normalize a cell value into a comparable string key (handles 123 vs '123' vs 123.0)."""
    if value is None:
        return None
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()


def get_sheet(wb, name):
    """Fetch a worksheet case-insensitively."""
    for sheet_name in wb.sheetnames:
        if sheet_name.strip().lower() == name.strip().lower():
            return wb[sheet_name]
    raise KeyError(f"Sheet '{name}' not found. Available sheets: {wb.sheetnames}")


def find_id_qty_columns(ws, max_scan_rows=10, max_scan_cols=30):
    """
    Locate the 'ID' and 'QTY' columns by scanning the first rows for headers.
    Returns (id_col, qty_col, header_row). Fallback: A=ID, B=QTY.
    """
    for r in range(1, min(ws.max_row, max_scan_rows) + 1):
        id_col = qty_col = None
        for c in range(1, min(ws.max_column, max_scan_cols) + 1):
            v = ws.cell(row=r, column=c).value
            if v is None:
                continue
            s = str(v).strip().upper()
            if s == "ID" and id_col is None:
                id_col = c
            elif s in ("QTY", "QUANTITY") and qty_col is None:
                qty_col = c
        if id_col and qty_col:
            return id_col, qty_col, r

    # Fallback: assume ID in col A and QTY in col B; decide if row 1 is a header
    first = norm_key(ws.cell(row=1, column=1).value)
    header_row = 1 if (first is None or first.upper() == "ID") else 0
    return 1, 2, header_row


def build_lookup(ws):
    """Build {normalized ID: QTY} mapping from a data sheet (first occurrence wins)."""
    id_col, qty_col, header_row = find_id_qty_columns(ws)
    lookup = {}
    for r in range(header_row + 1, ws.max_row + 1):
        key = norm_key(ws.cell(row=r, column=id_col).value)
        if not key or key.upper() == "ID":        # skip blanks / header text
            continue
        if key not in lookup:                     # VLOOKUP-like: first match wins
            lookup[key] = ws.cell(row=r, column=qty_col).value
    return lookup


def clean_qty(value):
    """Convert a looked-up QTY into the value to write ('-' for blank/error/missing)."""
    if value is None:
        return "-"
    if isinstance(value, str):
        s = value.strip()
        if s == "" or s.startswith("#"):          # blank or Excel error (#N/A, #REF!, ...)
            return "-"
        return s
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


